/**
 * Protected acceptance suite: bound probe intake and emit redacted structured verdicts.
 *
 * Test files only — no src changes. The Builder starts from this head and
 * must not edit this file. Do not edit this file to make an implementation
 * pass; return corrections to its author.
 *
 * Contract under test (builder: implement exactly this in bin/smoke.mjs):
 *
 * - Finite intake: both GET /health and GET /readyz enforce MAX_PROBE_BYTES
 *   (16_384) incrementally via the response body reader, never via a trusted
 *   Content-Length and never via unbounded response.text(). Exact-cap valid
 *   JSON passes; cap+1 valid JSON fails. Missing or lying Content-Length
 *   never bypasses the actual-byte count (small claim + large actual fails;
 *   large claim + small valid passes). Over-budget fails fast: the unread
 *   tail is cancelled best-effort (never awaited, even when cancel() never
 *   settles) and only a bounded prefix is pulled. A refused body is never
 *   valid health evidence, even when its prefix is well-formed JSON.
 * - Whole-request deadline preserved: the existing AbortSignal.timeout
 *   (default 5000 ms, or the caller's timeoutMs) still bounds headers+body.
 *   A sub-cap prefix followed by a forever-stalled tail settles FAIL at the
 *   deadline; a never-settling cancel never blocks settlement.
 * - Redacted diagnostics: remote version/security/media header values are
 *   never interpolated raw. Logs carry fixed mismatch codes or
 *   shape-validated bounded identifiers only. Hostile, control-char,
 *   overlong and secret-shaped header values fail (live mode requires a
 *   present lowercase-UUID version; override mode requires equality) and
 *   never appear in any log line. Raw bodies never appear either.
 * - JSON mode: `node bin/smoke.mjs <origin> --json` (and
 *   smoke(url, { json: true })) logs one machine-readable object with
 *   stable route IDs ["health","readyz"], per-route checks with stable
 *   "<route>.<name>" IDs, verdict pass/fail matching the boolean return,
 *   a shape-validated bounded reason_code (ok iff pass) and next_action
 *   (none iff pass). Default text CLI, --version-override contract and
 *   exit codes 0/1/2 stay compatible. Probes stay GET-only with
 *   redirect:"manual"; no --dry-run or mutation path is added.
 *
 * Preserved behavior pinned here: valid health/readiness/override pass in
 * text mode, manual 301/302 fails without following, --allow-indexable
 * stays a logged no-op, and unknown flags stay usage errors. The
 * TOG-29507 caller/override contract in smoke-checker.test.ts must keep
 * passing unchanged.
 *
 * Offline only: injected fetchImpl fakes with instrumented ReadableStreams
 * plus loopback 127.0.0.1 stubs for the CLI spawn. No staging, production,
 * database, Discord or secret is contacted.
 * Run: node --import ./test/cloudflare-loader.mjs --test test/smoke-bounded-intake-acceptance.test.ts
 * (from wrangler/; the loader is harmless here — this file imports only
 * Node builtins and ../../bin/smoke.mjs).
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { once } from "node:events";
import { fileURLToPath } from "node:url";
import {
  OVERRIDE_HEADER,
  VERSION_HEADER,
  parseArgs,
  smoke,
} from "../../bin/smoke.mjs";

const WORKER = "two-bot-next";
const NEW_VERSION = "22345678-1234-1234-1234-123456789abc";
const OLD_VERSION = "11111111-2222-3333-4444-555555555555";
const QUOTED = `${WORKER}="${NEW_VERSION}"`;

/** Documented finite budget under test: 16 KiB for each probe body. */
const MAX_PROBE_BYTES = 16 * 1024;
const SETTLE_BUDGET_MS = 800;
const SHRUNK_TIMEOUT_MS = 30;
const LARGE_BODY_BYTES = 128 * 1024;

const SENTINEL_BODY = "synthetic-body-sentinel-must-not-leak-0123456789";
// Hostile no-echo fixtures, runtime-built so no credential-shaped literal
// appears in source (secret scanners flag such literals even in tests).
const SECRET_TOKEN = ["synthetic", "probe-token", "must-not-leak", "0123456789abcdef"].join("-");
const SECRET_KEY = ["synthetic", "probe-key", "must-not-leak", "0123456789"].join("-");
const OVERLONG = "a".repeat(5000);
const CONTROL_NEWLINE = "evil-version\ninjected-header: yes";
const CONTROL_CRLF = "bad\r\nContent-Length: 9999";
const CONTROL_NUL = "nul-\u0000-ctrl-\u0001-end";
const EVIL_URL = "https://evil.example/exfil?token=abc123";
const EVIL_EMAIL = "secret-leak@example.com";

const HOSTILE_VERSIONS = [
  CONTROL_NEWLINE,
  CONTROL_CRLF,
  CONTROL_NUL,
  OVERLONG,
  SECRET_TOKEN,
  SECRET_KEY,
  EVIL_URL,
  EVIL_EMAIL,
];

const IDENT = /^[a-z][a-z0-9_]{0,63}$/;
const CHECK_ID = /^(health|readyz)\.[a-z0-9_]+$/;

function quiet() {
  const lines: string[] = [];
  return { log: (line: string) => void lines.push(line), lines };
}

function healthBodyExact(cap: number): string {
  const base = JSON.stringify({ status: "ok", pad: "" });
  const padLen = cap - base.length;
  assert.ok(padLen >= 0, `health cap ${cap} smaller than base ${base.length}`);
  const body = JSON.stringify({ status: "ok", pad: "x".repeat(padLen) });
  assert.equal(new TextEncoder().encode(body).byteLength, cap);
  return body;
}

function readyzBodyExact(cap: number): string {
  const base = JSON.stringify({ build_revision: "r", pad: "" });
  const padLen = cap - base.length;
  assert.ok(padLen >= 0, `readyz cap ${cap} smaller than base ${base.length}`);
  const body = JSON.stringify({ build_revision: "r", pad: "x".repeat(padLen) });
  assert.equal(new TextEncoder().encode(body).byteLength, cap);
  return body;
}

const HEALTH_SMALL = JSON.stringify({ status: "ok" });
const READYZ_SMALL = JSON.stringify({
  health: { components: [["process", "ready"], ["gateway", "ready"]] },
  build_revision: "abc123",
  build_id: "1-1",
});

function chunksOf(text: string, parts: number): Uint8Array[] {
  const bytes = new TextEncoder().encode(text);
  const out: Uint8Array[] = [];
  const size = Math.ceil(bytes.byteLength / parts);
  for (let i = 0; i < bytes.byteLength; i += size) out.push(bytes.slice(i, i + size));
  return out;
}

function instrumentedStream(
  chunks: Uint8Array[],
  opts: { stallAfter?: number; cancelStalls?: boolean } = {},
) {
  let index = 0;
  let pulledBytes = 0;
  let pulls = 0;
  let cancels = 0;
  const stream = new ReadableStream<Uint8Array>(
    {
      pull(controller) {
        pulls += 1;
        if (opts.stallAfter !== undefined && index >= opts.stallAfter) {
          return new Promise<void>(() => {});
        }
        if (index < chunks.length) {
          const chunk = chunks[index++]!;
          pulledBytes += chunk.byteLength;
          controller.enqueue(chunk);
          return;
        }
        controller.close();
      },
      cancel() {
        cancels += 1;
        if (opts.cancelStalls) return new Promise<void>(() => {});
      },
    },
    { highWaterMark: 0 },
  );
  return {
    stream,
    state: {
      pulledBytes: () => pulledBytes,
      pulls: () => pulls,
      cancels: () => cancels,
    },
  };
}

type FetchCall = { url: string; method?: string; redirect?: string; signal?: AbortSignal };

function fakeFetch(handler: (url: URL) => Response | Promise<Response>) {
  const calls: FetchCall[] = [];
  const fetchImpl = async (input: unknown, init?: Record<string, unknown>) => {
    const url = input instanceof URL ? input : new URL(String(input));
    calls.push({
      url: url.pathname,
      method: init?.["method"] as string | undefined,
      redirect: init?.["redirect"] as string | undefined,
      signal: init?.["signal"] as AbortSignal | undefined,
    });
    return handler(url);
  };
  return { fetchImpl: fetchImpl as typeof fetch, calls };
}

function jsonResponse(
  bodyStream: ReadableStream<Uint8Array>,
  opts: {
    status?: number;
    version?: string;
    contentLength?: string | null;
    omitVersion?: boolean;
  } = {},
): Response {
  const headers: Record<string, string> = {
    "content-type": "application/json; charset=utf-8",
    "x-content-type-options": "nosniff",
  };
  if (!opts.omitVersion) headers[VERSION_HEADER] = opts.version ?? NEW_VERSION;
  if (opts.contentLength !== undefined && opts.contentLength !== null) {
    headers["content-length"] = opts.contentLength;
  }
  return new Response(bodyStream, { status: opts.status ?? 200, headers });
}

/** Bypass Headers validation so hostile/control values reach the checker. */
function hostileResponse(opts: {
  status?: number;
  version?: string;
  security?: string | null;
  contentType?: string | null;
  bodyText?: string;
}) {
  const bodyText = opts.bodyText ?? HEALTH_SMALL;
  const bytes = new TextEncoder().encode(bodyText);
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(bytes);
      controller.close();
    },
  });
  const map: Record<string, string> = {};
  if (opts.version !== undefined) map[VERSION_HEADER] = opts.version;
  if (opts.security !== undefined && opts.security !== null) {
    map["x-content-type-options"] = opts.security;
  }
  if (opts.contentType !== undefined && opts.contentType !== null) {
    map["content-type"] = opts.contentType;
  }
  return {
    status: opts.status ?? 200,
    headers: {
      get: (name: string) => map[name.toLowerCase()] ?? null,
    },
    text: async () => bodyText,
    body: stream,
  } as unknown as Response;
}

async function settleWithin<T>(work: Promise<T>, label: string): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const guard = new Promise<never>((_, reject) => {
    timer = setTimeout(
      () => reject(new Error(`${label} did not settle within ${SETTLE_BUDGET_MS}ms`)),
      SETTLE_BUDGET_MS,
    );
  });
  try {
    return await Promise.race([work, guard]);
  } finally {
    clearTimeout(timer);
  }
}

function assertGetOnlyManual(calls: FetchCall[], label: string) {
  assert.ok(calls.length >= 2, `${label}: expected at least 2 probes, got ${calls.length}`);
  for (const call of calls) {
    assert.equal(call.method, "GET", `${label}: probes stay GET-only`);
    assert.equal(call.redirect, "manual", `${label}: manual redirects preserved`);
  }
}

function findJson(lines: string[]): Record<string, unknown> | undefined {
  for (const line of lines) {
    try {
      const parsed = JSON.parse(line) as Record<string, unknown>;
      if (parsed && typeof parsed === "object" && "verdict" in parsed) return parsed;
    } catch {
      // Not JSON; keep scanning.
    }
  }
  return undefined;
}

function assertNoEcho(lines: string[], forbidden: string[], label: string) {
  for (const secret of forbidden) {
    assert.ok(
      lines.every((line) => !line.includes(secret)),
      `${label}: diagnostics must never echo ${JSON.stringify(secret.slice(0, 40))}`,
    );
  }
}

// ---------------------------------------------------------------------------
// Byte budget: exact/at/over, chunked, missing/lying length, prompt cancel.
// ---------------------------------------------------------------------------

test("health: exact-cap passes, cap+1 valid JSON fails (never valid evidence)", async () => {
  const exact = healthBodyExact(MAX_PROBE_BYTES);
  const over = healthBodyExact(MAX_PROBE_BYTES + 1);
  for (const [body, want, label] of [
    [exact, true, "exact-cap"],
    [over, false, "cap+1"],
  ] as const) {
    const streams = {
      "/health": instrumentedStream(chunksOf(body, 1)),
      "/readyz": instrumentedStream(chunksOf(READYZ_SMALL, 1)),
    };
    const { fetchImpl } = fakeFetch((url) => {
      const key = url.pathname as keyof typeof streams;
      return jsonResponse(streams[key].stream);
    });
    const { log } = quiet();
    const ok = await settleWithin(
      smoke("http://probe.invalid", { log, fetchImpl }),
      `health ${label}`,
    );
    assert.equal(ok, want, `health ${label} body must ${want ? "pass" : "fail"}`);
  }
});

test("readyz: exact-cap passes, cap+1 valid JSON fails (never valid evidence)", async () => {
  const exact = readyzBodyExact(MAX_PROBE_BYTES);
  const over = readyzBodyExact(MAX_PROBE_BYTES + 1);
  for (const [body, want, label] of [
    [exact, true, "exact-cap"],
    [over, false, "cap+1"],
  ] as const) {
    const streams = {
      "/health": instrumentedStream(chunksOf(HEALTH_SMALL, 1)),
      "/readyz": instrumentedStream(chunksOf(body, 1)),
    };
    const { fetchImpl } = fakeFetch((url) => {
      const key = url.pathname as keyof typeof streams;
      return jsonResponse(streams[key].stream);
    });
    const { log } = quiet();
    const ok = await settleWithin(
      smoke("http://probe.invalid", { log, fetchImpl }),
      `readyz ${label}`,
    );
    assert.equal(ok, want, `readyz ${label} body must ${want ? "pass" : "fail"}`);
  }
});

test("chunked bodies below/at/over budget enforce actual bytes", async () => {
  const below = healthBodyExact(MAX_PROBE_BYTES - 10);
  const at = healthBodyExact(MAX_PROBE_BYTES);
  const over = healthBodyExact(MAX_PROBE_BYTES + 1);
  for (const [body, want, label] of [
    [below, true, "below-cap chunked"],
    [at, true, "at-cap chunked"],
    [over, false, "over-cap chunked"],
  ] as const) {
    const health = instrumentedStream(chunksOf(body, 7));
    const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 3));
    const { fetchImpl } = fakeFetch((url) =>
      url.pathname === "/health" ? jsonResponse(health.stream) : jsonResponse(readyz.stream),
    );
    const { log } = quiet();
    const ok = await settleWithin(
      smoke("http://probe.invalid", { log, fetchImpl }),
      label,
    );
    assert.equal(ok, want, `${label} must ${want ? "pass" : "fail"}`);
  }
});

test("missing Content-Length still enforces the byte budget", async () => {
  for (const [body, want, label] of [
    [HEALTH_SMALL, true, "small without length"],
    [healthBodyExact(MAX_PROBE_BYTES + 1), false, "over-cap without length"],
  ] as const) {
    const health = instrumentedStream(chunksOf(body, 4));
    const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 1));
    const { fetchImpl } = fakeFetch((url) =>
      url.pathname === "/health"
        ? jsonResponse(health.stream, { contentLength: null })
        : jsonResponse(readyz.stream, { contentLength: null }),
    );
    const { log } = quiet();
    const ok = await settleWithin(
      smoke("http://probe.invalid", { log, fetchImpl }),
      label,
    );
    assert.equal(ok, want, `${label} must ${want ? "pass" : "fail"}`);
  }
});

test("lying Content-Length never decides: small claim + large actual fails, large claim + small valid passes", async () => {
  // Dishonest small claim must not smuggle an over-budget body through.
  {
    const health = instrumentedStream(chunksOf(healthBodyExact(MAX_PROBE_BYTES + 500), 5));
    const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 1));
    const { fetchImpl } = fakeFetch((url) =>
      url.pathname === "/health"
        ? jsonResponse(health.stream, { contentLength: "10" })
        : jsonResponse(readyz.stream),
    );
    const { log } = quiet();
    const ok = await settleWithin(
      smoke("http://probe.invalid", { log, fetchImpl }),
      "lying small claim",
    );
    assert.equal(ok, false, "over-budget actual with a lying small claim must fail");
  }
  // Dishonest large claim must not refuse a small valid body.
  {
    const health = instrumentedStream(chunksOf(HEALTH_SMALL, 1));
    const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 1));
    const { fetchImpl } = fakeFetch((url) =>
      url.pathname === "/health"
        ? jsonResponse(health.stream, { contentLength: String(10 * 1024 * 1024) })
        : jsonResponse(readyz.stream),
    );
    const { log } = quiet();
    const ok = await settleWithin(
      smoke("http://probe.invalid", { log, fetchImpl }),
      "lying large claim",
    );
    assert.equal(ok, true, "small valid actual with a lying large claim must pass");
  }
});

test("over-budget cancels promptly and pulls a bounded prefix, not the tail", async () => {
  const big = healthBodyExact(LARGE_BODY_BYTES);
  const health = instrumentedStream(chunksOf(big, 64));
  const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 1));
  const { fetchImpl } = fakeFetch((url) =>
    url.pathname === "/health" ? jsonResponse(health.stream) : jsonResponse(readyz.stream),
  );
  const { log } = quiet();
  const ok = await settleWithin(
    smoke("http://probe.invalid", { log, fetchImpl }),
    "over-budget cancel",
  );
  assert.equal(ok, false, "128 KiB valid-shaped body must fail the 16 KiB budget");
  assert.ok(health.state.cancels() >= 1, "unread tail must be cancelled promptly");
  assert.ok(
    health.state.pulledBytes() < MAX_PROBE_BYTES * 2,
    `must pull a bounded prefix, pulled ${health.state.pulledBytes()} of ${LARGE_BODY_BYTES}`,
  );
});

test("stalled tail after a sub-cap prefix settles FAIL at the deadline", async () => {
  const prefix = new TextEncoder().encode('{"status":');
  const health = instrumentedStream([prefix], { stallAfter: 1 });
  const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 1));
  const { fetchImpl } = fakeFetch((url) =>
    url.pathname === "/health" ? jsonResponse(health.stream) : jsonResponse(readyz.stream),
  );
  const { log } = quiet();
  const ok = await settleWithin(
    smoke("http://probe.invalid", { log, fetchImpl, timeoutMs: SHRUNK_TIMEOUT_MS }),
    "stalled tail",
  );
  assert.equal(ok, false, "stalled body must fail, never hang or pass");
  assert.ok(health.state.cancels() >= 1, "stalled body cleanup is attempted");
});

test("never-settling cancel never blocks the over-budget FAIL", async () => {
  const health = instrumentedStream(chunksOf(healthBodyExact(MAX_PROBE_BYTES + 1), 2), {
    cancelStalls: true,
  });
  const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 1));
  const { fetchImpl } = fakeFetch((url) =>
    url.pathname === "/health" ? jsonResponse(health.stream) : jsonResponse(readyz.stream),
  );
  const { log } = quiet();
  const ok = await settleWithin(
    smoke("http://probe.invalid", { log, fetchImpl, timeoutMs: SHRUNK_TIMEOUT_MS }),
    "never-settling cancel",
  );
  assert.equal(ok, false, "over-budget must fail without awaiting a stalled cancel");
  assert.ok(health.state.cancels() >= 1, "cancellation is attempted best-effort");
});

test("whole-request deadline is preserved: timeoutMs reaches AbortSignal.timeout", async (t) => {
  const seen: number[] = [];
  const realTimeout = AbortSignal.timeout;
  t.mock.method(AbortSignal, "timeout", (ms: number) => {
    seen.push(ms);
    return realTimeout(SHRUNK_TIMEOUT_MS);
  });
  const health = instrumentedStream(chunksOf(HEALTH_SMALL, 1));
  const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 1));
  const { fetchImpl, calls } = fakeFetch((url) =>
    url.pathname === "/health" ? jsonResponse(health.stream) : jsonResponse(readyz.stream),
  );
  const { log } = quiet();
  const ok = await settleWithin(
    smoke("http://probe.invalid", { log, fetchImpl, timeoutMs: 1234 }),
    "deadline preserved",
  );
  assert.equal(ok, true, "small valid bodies stay inside the deadline");
  assert.ok(seen.includes(1234), `timeoutMs must reach AbortSignal.timeout, saw ${seen}`);
  assertGetOnlyManual(calls, "deadline");
});

// ---------------------------------------------------------------------------
// Redacted diagnostics: hostile/control/overlong/secret values never echo.
// ---------------------------------------------------------------------------

test("live hostile versions fail without echo (shape-validated bounded IDs only)", async () => {
  for (const hostile of HOSTILE_VERSIONS) {
    const { fetchImpl } = fakeFetch((url) =>
      url.pathname === "/health"
        ? hostileResponse({ version: hostile, security: "nosniff", contentType: "application/json" })
        : jsonResponse(instrumentedStream(chunksOf(READYZ_SMALL, 1)).stream),
    );
    const { log, lines } = quiet();
    const ok = await settleWithin(smoke("http://probe.invalid", { log, fetchImpl }), "hostile live");
    assert.equal(ok, false, `live hostile version ${JSON.stringify(hostile.slice(0, 20))} must fail`);
    assertNoEcho(lines, [hostile], "live hostile version");
  }
});

test("override hostile versions fail without echo", async () => {
  for (const hostile of HOSTILE_VERSIONS) {
    const { fetchImpl } = fakeFetch((url) =>
      hostileResponse({ version: hostile, security: "nosniff", contentType: "application/json" }),
    );
    const { log, lines } = quiet();
    const ok = await settleWithin(
      smoke("http://probe.invalid", { log, fetchImpl, versionOverride: QUOTED }),
      "hostile override",
    );
    assert.equal(ok, false, "mismatched hostile version must fail");
    assertNoEcho(lines, [hostile], "override hostile version");
  }
});

test("hostile security/media headers fail without echo", async () => {
  const cases = [
    { security: CONTROL_NEWLINE, contentType: "application/json" as const },
    { security: OVERLONG, contentType: "application/json" as const },
    { security: SECRET_TOKEN, contentType: "application/json" as const },
    { security: "nosniff", contentType: `text/html\ninjected: ${SECRET_TOKEN}` },
    { security: "nosniff", contentType: OVERLONG },
    { security: CONTROL_CRLF, contentType: CONTROL_NUL },
  ];
  for (const hostile of cases) {
    const { fetchImpl } = fakeFetch((url) =>
      url.pathname === "/health"
        ? hostileResponse({ version: NEW_VERSION, ...hostile })
        : jsonResponse(instrumentedStream(chunksOf(READYZ_SMALL, 1)).stream),
    );
    const { log, lines } = quiet();
    const ok = await settleWithin(smoke("http://probe.invalid", { log, fetchImpl }), "hostile headers");
    assert.equal(ok, false, "hostile security/media headers must fail");
    assertNoEcho(lines, [hostile.security, hostile.contentType], "hostile security/media");
  }
});

test("raw bodies never appear in diagnostics", async () => {
  const bodyWithSentinel = JSON.stringify({ status: "ok", leak: SENTINEL_BODY });
  const health = instrumentedStream(chunksOf(bodyWithSentinel, 2));
  const readyz = instrumentedStream(chunksOf(READYZ_SMALL, 1));
  const { fetchImpl } = fakeFetch((url) =>
    url.pathname === "/health" ? jsonResponse(health.stream) : jsonResponse(readyz.stream),
  );
  const { log, lines } = quiet();
  const ok = await settleWithin(smoke("http://probe.invalid", { log, fetchImpl }), "sentinel body");
  assert.equal(ok, true, "small valid body with a sentinel value still passes");
  assertNoEcho(lines, [SENTINEL_BODY], "raw body");

  const overWithSentinel = JSON.stringify({
    status: "ok",
    pad: "x".repeat(MAX_PROBE_BYTES),
    leak: SENTINEL_BODY,
  });
  const healthOver = instrumentedStream(chunksOf(overWithSentinel, 8));
  const readyzOver = instrumentedStream(chunksOf(READYZ_SMALL, 1));
  const overFetch = fakeFetch((url) =>
    url.pathname === "/health" ? jsonResponse(healthOver.stream) : jsonResponse(readyzOver.stream),
  );
  const overLogs = quiet();
  const overOk = await settleWithin(
    smoke("http://probe.invalid", { log: overLogs.log, fetchImpl: overFetch.fetchImpl }),
    "over-budget sentinel",
  );
  assert.equal(overOk, false, "over-budget body with a sentinel must fail");
  assertNoEcho(overLogs.lines, [SENTINEL_BODY], "over-budget raw body");
});

// ---------------------------------------------------------------------------
// JSON mode: stable IDs, verdict, reason code, next action; CLI compatible.
// ---------------------------------------------------------------------------

test("parseArgs accepts --json, keeps stage shapes, and rejects --dry-run", () => {
  const withJson = parseArgs(["https://probe.invalid", "--json"]);
  assert.equal((withJson as { json?: boolean }).json, true);
  const staged = parseArgs([
    "https://probe.invalid",
    "--allow-indexable",
    "--version-override",
    QUOTED,
    "--json",
  ]);
  assert.equal(staged.versionOverride, QUOTED);
  assert.equal(staged.allowIndexable, true);
  assert.equal((staged as { json?: boolean }).json, true);
  const plain = parseArgs(["https://probe.invalid"]);
  assert.equal((plain as { json?: boolean }).json ?? false, false);
  assert.throws(() => parseArgs(["https://probe.invalid", "--dry-run"]), /Usage/);
});

function assertSmokeJson(
  doc: Record<string, unknown> | undefined,
  wantPass: boolean,
  label: string,
): { routeIds: string[]; checkIds: string[] } {
  assert.ok(doc, `${label}: JSON mode must log one parseable verdict object`);
  assert.equal(doc["schema"], "smoke.v1", `${label}: stable schema tag`);
  assert.equal(doc["verdict"], wantPass ? "pass" : "fail", `${label}: verdict matches outcome`);
  const reason = doc["reason_code"];
  const action = doc["next_action"];
  assert.equal(typeof reason, "string", `${label}: reason_code is a string`);
  assert.equal(typeof action, "string", `${label}: next_action is a string`);
  assert.ok(IDENT.test(reason as string), `${label}: reason_code is a bounded identifier`);
  assert.ok(IDENT.test(action as string), `${label}: next_action is a bounded identifier`);
  assert.equal(reason, wantPass ? "ok" : reason, `${label}: pass carries reason ok`);
  assert.equal(action, wantPass ? "none" : action, `${label}: pass carries action none`);
  if (!wantPass) {
    assert.notEqual(reason, "ok", `${label}: fail carries a non-ok reason`);
    assert.notEqual(action, "none", `${label}: fail carries a follow-up action`);
  }
  const routes = doc["routes"] as Array<Record<string, unknown>>;
  assert.ok(Array.isArray(routes), `${label}: routes is an array`);
  assert.deepEqual(
    routes.map((r) => r["id"]),
    ["health", "readyz"],
    `${label}: stable route IDs in order`,
  );
  const checkIds: string[] = [];
  for (const route of routes) {
    assert.equal(typeof route["ok"], "boolean", `${label}: route ok is boolean`);
    const checks = route["checks"] as Array<Record<string, unknown>>;
    assert.ok(Array.isArray(checks) && checks.length > 0, `${label}: route has checks`);
    for (const check of checks) {
      assert.equal(typeof check["id"], "string", `${label}: check id is a string`);
      assert.ok(CHECK_ID.test(check["id"] as string), `${label}: stable check ID shape`);
      assert.ok(
        (check["id"] as string).startsWith(`${route["id"] as string}.`),
        `${label}: check ID names its route`,
      );
      assert.equal(typeof check["ok"], "boolean", `${label}: check ok is boolean`);
      assert.equal(typeof check["code"], "string", `${label}: check code is a string`);
      assert.ok(IDENT.test(check["code"] as string), `${label}: check code is a bounded identifier`);
      checkIds.push(check["id"] as string);
    }
  }
  return { routeIds: ["health", "readyz"], checkIds };
}

