test("control: valid text probes pass with and without the override", async () => {
  for (const override of [undefined, QUOTED] as const) {
    const { fetchImpl, calls } = fakeFetch((url) =>
      url.pathname === "/health"
        ? jsonResponse(instrumentedStream(chunksOf(HEALTH_SMALL, 1)).stream)
        : jsonResponse(instrumentedStream(chunksOf(READYZ_SMALL, 1)).stream),
    );
    const { log, lines } = quiet();
    const ok = await settleWithin(
      smoke("http://probe.invalid", { log, fetchImpl, versionOverride: override }),
      `valid ${override ? "override" : "live"}`,
    );
    assert.equal(ok, true, `valid ${override ? "override" : "live"} text probe passes`);
    assert.ok(lines.some((line) => line.includes("PASS /health")));
    assert.ok(lines.some((line) => line.includes("PASS /readyz")));
    assertGetOnlyManual(calls, "valid text");
    if (override !== undefined) {
      const seen = calls.map(() => override);
      assert.ok(seen.length >= 2, "override probes still run both routes");
    }
  }
});

